  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.api.ApiController;
  7	import com.pousadamarealta.repository.Database;
  8	import com.pousadamarealta.repository.MessageRepository;
  9	import com.pousadamarealta.repository.ReservationRepository;
 10	import com.pousadamarealta.repository.RoomRepository;
 11	import com.pousadamarealta.service.PricingService;
 12	import com.pousadamarealta.service.ReportService;
 13	import com.pousadamarealta.service.ReservationService;
 14	import io.javalin.Javalin;
 15	import io.javalin.json.JavalinJackson;
 16	
 17	public class App {
 18	    public static void main(String[] args) {
 19	        String dbUrl = System.getenv("DB_URL");
 20	        String dbUser = System.getenv("DB_USER");
 21	        String dbPassword = System.getenv("DB_PASSWORD");
 22	        String portEnv = System.getenv("PORT");
 23	        int port = portEnv != null ? Integer.parseInt(portEnv) : 7070;
 24	
 25	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 26	            throw new RuntimeException("Database configuration not provided");
 27	        }
 28	
 29	        Database database = new Database(dbUrl, dbUser, dbPassword);
 30	        database.initialize();
 31	
 32	        RoomRepository roomRepository = new RoomRepository(database);
 33	        ReservationRepository reservationRepository = new ReservationRepository(database);
 34	        MessageRepository messageRepository = new MessageRepository(database);
 35	
 36	        PricingService pricingService = new PricingService();
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository,
 39	            roomRepository,
 40	            messageRepository,
 41	            pricingService
 42	        );
 43	        ReportService reportService = new ReportService(reservationRepository);
 44	
 45	        ObjectMapper objectMapper = new ObjectMapper();
 46	        objectMapper.registerModule(new JavaTimeModule());
 47	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 48	
 49	        Javalin app = Javalin.create(config -> {
 50	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 51	        });
 52	
 53	        ApiController controller = new ApiController(
 54	            roomRepository,
 55	            reservationService,
 56	            messageRepository,
 57	            reportService
 58	        );
 59	        controller.registerRoutes(app);
 60	
 61	        app.start(port);
 62	
 63	        System.out.println("Pousada Maré Alta reservation system started on port " + port);
 64	    }
 65	}
 66	package com.pousadamarealta.api;
 67	
 68	import com.pousadamarealta.domain.*;
 69	import com.pousadamarealta.repository.MessageRepository;
 70	import com.pousadamarealta.repository.RoomRepository;
 71	import com.pousadamarealta.service.*;
 72	import io.javalin.Javalin;
 73	import io.javalin.http.Context;
 74	
 75	import java.time.LocalDate;
 76	import java.time.YearMonth;
 77	import java.time.format.DateTimeParseException;
 78	import java.util.List;
 79	
 80	public class ApiController {
 81	    private final RoomRepository roomRepository;
 82	    private final ReservationService reservationService;
 83	    private final MessageRepository messageRepository;
 84	    private final ReportService reportService;
 85	
 86	    public ApiController(RoomRepository roomRepository,
 87	                        ReservationService reservationService,
 88	                        MessageRepository messageRepository,
 89	                        ReportService reportService) {
 90	        this.roomRepository = roomRepository;
 91	        this.reservationService = reservationService;
 92	        this.messageRepository = messageRepository;
 93	        this.reportService = reportService;
 94	    }
 95	
 96	    public void registerRoutes(Javalin app) {
 97	        app.get("/rooms", this::getRooms);
 98	        app.post("/reservations", this::createReservation);
 99	        app.get("/reservations/{id}", this::getReservation);
100	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
101	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
102	        app.post("/reservations/{id}/check-in", this::checkIn);
103	        app.post("/reservations/{id}/check-out", this::checkOut);
104	        app.get("/reservations/{id}/document", this::getDocument);
105	        app.get("/messages", this::getMessages);
106	        app.get("/reports/occupancy", this::getOccupancyReport);
107	        app.get("/reports/revenue", this::getRevenueReport);
108	
109	        app.exception(InvalidRequestException.class, (e, ctx) -> {
110	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
111	        });
112	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
113	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
114	        });
115	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
116	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
117	        });
118	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
119	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
120	        });
121	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
122	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
123	        });
124	        app.exception(CapacityExceededException.class, (e, ctx) -> {
125	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
126	        });
127	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
128	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
129	        });
130	        app.exception(DateTimeParseException.class, (e, ctx) -> {
131	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
132	        });
133	    }
134	
135	    private void getRooms(Context ctx) {
136	        List<Room> rooms = roomRepository.findAll();
137	        ctx.json(rooms.stream().map(RoomResponse::from).toList());
138	    }
139	
140	    private void createReservation(Context ctx) {
141	        try {
142	            ReservationRequest request = ctx.bodyAsClass(ReservationRequest.class);
143	
144	            if (request.roomNumber() == null || request.guestName() == null ||
145	                request.guestEmail() == null || request.guestCpf() == null ||
146	                request.checkIn() == null || request.checkOut() == null ||
147	                request.guests() == null || request.ratePlan() == null) {
148	                throw new InvalidRequestException("Missing required fields");
149	            }
150	
151	            Reservation reservation = new Reservation();
152	            reservation.setRoomNumber(request.roomNumber());
153	            reservation.setGuestName(request.guestName());
154	            reservation.setGuestEmail(request.guestEmail());
155	            reservation.setGuestCpf(request.guestCpf());
156	            reservation.setCheckIn(request.checkIn());
157	            reservation.setCheckOut(request.checkOut());
158	            reservation.setGuests(request.guests());
159	            reservation.setRatePlan(request.ratePlan());
160	            reservation.setCompanyCode(request.companyCode());
161	
162	            Reservation created = reservationService.createReservation(reservation);
163	            ctx.status(201).json(ReservationResponse.from(created));
164	        } catch (Exception e) {
165	            if (e instanceof InvalidRequestException ||
166	                e instanceof RoomNotFoundException ||
167	                e instanceof RoomUnavailableException ||
168	                e instanceof CapacityExceededException ||
169	                e instanceof IllegalArgumentException) {
170	                throw e;
171	            }
172	            throw new InvalidRequestException("Invalid request: " + e.getMessage());
173	        }
174	    }
175	
176	    private void getReservation(Context ctx) {
177	        Long id = ctx.pathParamAsClass("id", Long.class).get();
178	        Reservation reservation = reservationService.getReservation(id);
179	        ctx.json(ReservationResponse.from(reservation));
180	    }
181	
182	    private void confirmReservation(Context ctx) {
183	        Long id = ctx.pathParamAsClass("id", Long.class).get();
184	        Reservation reservation = reservationService.confirmReservation(id);
185	        ctx.json(ReservationResponse.from(reservation));
186	    }
187	
188	    private void cancelReservation(Context ctx) {
189	        Long id = ctx.pathParamAsClass("id", Long.class).get();
190	        Reservation reservation = reservationService.cancelReservation(id);
191	        ctx.json(ReservationResponse.from(reservation));
192	    }
193	
194	    private void checkIn(Context ctx) {
195	        Long id = ctx.pathParamAsClass("id", Long.class).get();
196	        Reservation reservation = reservationService.checkIn(id);
197	        ctx.json(ReservationResponse.from(reservation));
198	    }
199	
200	    private void checkOut(Context ctx) {
201	        Long id = ctx.pathParamAsClass("id", Long.class).get();
202	        Reservation reservation = reservationService.checkOut(id);
203	        ctx.json(DocumentResponse.from(reservation));
204	    }
205	
206	    private void getDocument(Context ctx) {
207	        Long id = ctx.pathParamAsClass("id", Long.class).get();
208	        Reservation reservation = reservationService.getReservation(id);
209	
210	        if (!reservation.isPaid()) {
211	            throw new OperationNotAllowedException("Document only available for paid reservations");
212	        }
213	
214	        ctx.json(DocumentResponse.from(reservation));
215	    }
216	
217	    private void getMessages(Context ctx) {
218	        List<Message> messages = messageRepository.findAll();
219	        ctx.json(messages.stream().map(MessageResponse::from).toList());
220	    }
221	
222	    private void getOccupancyReport(Context ctx) {
223	        String dateParam = ctx.queryParam("date");
224	        if (dateParam == null) {
225	            throw new InvalidRequestException("Missing date parameter");
226	        }
227	
228	        LocalDate date = LocalDate.parse(dateParam);
229	        String csv = reportService.generateOccupancyReport(date);
230	
231	        ctx.contentType("text/csv; charset=utf-8").result(csv);
232	    }
233	
234	    private void getRevenueReport(Context ctx) {
235	        String monthParam = ctx.queryParam("month");
236	        if (monthParam == null) {
237	            throw new InvalidRequestException("Missing month parameter");
238	        }
239	
240	        YearMonth month = YearMonth.parse(monthParam);
241	        String csv = reportService.generateRevenueReport(month);
242	
243	        ctx.contentType("text/csv; charset=utf-8").result(csv);
244	    }
245	}

