224	import java.util.Map;
225	
226	public class PricingService {
227	
228	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
229	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
230	        "TECNOSUL", new BigDecimal("0.12"),
231	        "AGROVALE", new BigDecimal("0.18"),
232	        "FARMAVIDA", new BigDecimal("0.25")
233	    );
234	    private static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
235	        RoomType.STANDARD, new BigDecimal("520.00"),
236	        RoomType.DELUXE, new BigDecimal("820.00"),
237	        RoomType.SUITE, new BigDecimal("1200.00")
238	    );
239	
240	    public void calculatePricing(Reservation reservation, Room room) {
241	        int nights = (int) reservation.getCheckIn().datesUntil(reservation.getCheckOut()).count();
242	        reservation.setNights(nights);
243	
244	        switch (reservation.getRatePlan()) {
245	            case WEEKEND_PACKAGE -> calculateWeekendPackage(reservation, room);
246	            case CORPORATE -> calculateCorporate(reservation, room);
247	            case LONG_STAY -> calculateLongStay(reservation, room);
248	            case NON_REFUNDABLE -> calculateNonRefundable(reservation, room);
249	            default -> calculateStandard(reservation, room);
250	        }
251	    }
252	
253	    private void calculateStandard(Reservation reservation, Room room) {
254	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
255	        reservation.setSubtotal(subtotal);
256	        reservation.setDiscount(BigDecimal.ZERO);
257	        reservation.setTotal(subtotal);
258	    }
259	
260	    private void calculateNonRefundable(Reservation reservation, Room room) {
261	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
262	        reservation.setSubtotal(subtotal);
263	
264	        BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
265	        discount = roundHalfToEven(discount);
266	        reservation.setDiscount(discount);
267	
268	        BigDecimal total = subtotal.subtract(discount);
269	        reservation.setTotal(total);
270	    }
271	
272	    private void calculateCorporate(Reservation reservation, Room room) {
273	        String companyCode = reservation.getCompanyCode();
274	        if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
275	            throw new IllegalArgumentException("Invalid company code for corporate rate plan");
276	        }
277	
278	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
279	        reservation.setSubtotal(subtotal);
280	
281	        BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
282	        BigDecimal discount = subtotal.multiply(discountRate);
283	        discount = roundHalfToEven(discount);
284	        reservation.setDiscount(discount);
285	
286	        BigDecimal total = subtotal.subtract(discount);
287	        reservation.setTotal(total);
288	    }
