290	    private void calculateWeekendPackage(Reservation reservation, Room room) {
291	        if (reservation.getNights() != 2) {
292	            throw new IllegalArgumentException("Weekend package requires exactly 2 nights");
293	        }
294	
295	        LocalDate checkIn = reservation.getCheckIn();
296	        LocalDate checkOut = reservation.getCheckOut();
297	
298	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY || checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
299	            throw new IllegalArgumentException("Weekend package must be Friday to Sunday");
300	        }
301	
302	        BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.getType());
303	        reservation.setSubtotal(packagePrice);
304	        reservation.setDiscount(BigDecimal.ZERO);
305	        reservation.setTotal(packagePrice);
306	    }
307	
308	    private void calculateLongStay(Reservation reservation, Room room) {
309	        if (reservation.getNights() < 7) {
310	            throw new IllegalArgumentException("Long stay requires at least 7 nights");
311	        }
312	
313	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
314	        reservation.setSubtotal(subtotal);
315	
316	        BigDecimal discount = subtotal.multiply(new BigDecimal("0.10"));
317	        discount = roundHalfToEven(discount);
318	        reservation.setDiscount(discount);
319	
320	        BigDecimal total = subtotal.subtract(discount);
321	        reservation.setTotal(total);
322	    }
323	
324	    private BigDecimal calculateSubtotal(Reservation reservation, BigDecimal baseRate) {
325	        BigDecimal subtotal = BigDecimal.ZERO;
326	
327	        LocalDate date = reservation.getCheckIn();
328	        while (date.isBefore(reservation.getCheckOut())) {
329	            BigDecimal nightRate = baseRate;
330	            if (isHighSeason(date)) {
331	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER);
332	                nightRate = roundHalfToEven(nightRate);
333	            }
334	            subtotal = subtotal.add(nightRate);
335	            date = date.plusDays(1);
336	        }
337	
338	        return roundHalfToEven(subtotal);
339	    }
340	
341	    private boolean isHighSeason(LocalDate date) {
342	        Month month = date.getMonth();
343	        int day = date.getDayOfMonth();
344	
345	        if (month == Month.JULY) {
346	            return true;
347	        }
348	
349	        if (month == Month.DECEMBER && day >= 15) {
350	            return true;
351	        }
352	
353	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
354	            return true;
355	        }
356	
357	        return false;
358	    }
359	
360	    public BigDecimal calculateRefund(Reservation reservation) {
361	        if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
362	            return BigDecimal.ZERO;
363	        }
364	
365	        BigDecimal refundAmount = switch (reservation.getRatePlan()) {
366	            case NON_REFUNDABLE -> BigDecimal.ZERO;
367	            case WEEKEND_PACKAGE -> {
368	                BigDecimal half = reservation.getAmountPaid().divide(new BigDecimal("2"), 10, RoundingMode.HALF_EVEN);
369	                yield roundHalfToEven(half);
370	            }
371	            default -> reservation.getAmountPaid();
372	        };
373	
374	        return refundAmount;
375	    }
376	
377	    private BigDecimal roundHalfToEven(BigDecimal value) {
378	        return value.setScale(2, RoundingMode.HALF_EVEN);
379	    }
380	}

