  1	package com.pousadamarealta.service;
  2	
  3	import com.pousadamarealta.domain.*;
  4	import com.pousadamarealta.repository.MessageRepository;
  5	import com.pousadamarealta.repository.ReservationRepository;
  6	import com.pousadamarealta.repository.RoomRepository;
  7	
  8	import java.time.LocalDate;
  9	import java.util.List;
 10	
 11	public class ReservationService {
 12	    private final ReservationRepository reservationRepository;
 13	    private final RoomRepository roomRepository;
 14	    private final MessageRepository messageRepository;
 15	    private final PricingService pricingService;
 16	
 17	    public ReservationService(ReservationRepository reservationRepository,
 18	                             RoomRepository roomRepository,
 19	                             MessageRepository messageRepository,
 20	                             PricingService pricingService) {
 21	        this.reservationRepository = reservationRepository;
 22	        this.roomRepository = roomRepository;
 23	        this.messageRepository = messageRepository;
 24	        this.pricingService = pricingService;
 25	    }
 26	
 27	    public Reservation createReservation(Reservation reservation) {
 28	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
 29	            .orElseThrow(() -> new RoomNotFoundException("Room not found"));
 30	
 31	        validateReservationRequest(reservation, room);
 32	
 33	        pricingService.calculatePricing(reservation, room);
 34	
 35	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(
 36	            reservation.getRoomNumber(),
 37	            reservation.getCheckIn(),
 38	            reservation.getCheckOut()
 39	        );
 40	
 41	        if (!conflicts.isEmpty()) {
 42	            throw new RoomUnavailableException("Room is not available for the selected dates");
 43	        }
 44	
 45	        return reservationRepository.save(reservation);
 46	    }
 47	
 48	    private void validateReservationRequest(Reservation reservation, Room room) {
 49	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
 50	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
 51	            throw new InvalidRequestException("Check-out must be after check-in");
 52	        }
 53	
 54	        if (reservation.getGuests() < 1) {
 55	            throw new InvalidRequestException("At least one guest is required");
 56	        }
 57	
 58	        if (reservation.getGuests() > room.getCapacity()) {
 59	            throw new CapacityExceededException("Number of guests exceeds room capacity");
 60	        }
 61	    }
 62	
 63	    public Reservation getReservation(Long id) {
 64	        return reservationRepository.findById(id)
 65	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
 66	    }
 67	
 68	    public Reservation confirmReservation(Long id) {
 69	        Reservation reservation = getReservation(id);
 70	
 71	        try {
 72	            reservation.confirm();
 73	        } catch (IllegalStateException e) {
 74	            throw new OperationNotAllowedException(e.getMessage());
 75	        }
 76	
 77	        reservationRepository.save(reservation);
 78	        sendConfirmationEmail(reservation);
 79	
 80	        return reservation;
 81	    }
 82	
 83	    public Reservation cancelReservation(Long id) {
 84	        Reservation reservation = getReservation(id);
 85	
 86	        try {
 87	            var refund = pricingService.calculateRefund(reservation);
