 98	
 99	public class MessageRepository {
100	    private final Database database;
101	
102	    public MessageRepository(Database database) {
103	        this.database = database;
104	    }
105	
106	    public Message save(Message message) {
107	        String sql = """
108	            INSERT INTO messages (channel, recipient, subject, body)
109	            VALUES (?, ?, ?, ?)
110	            RETURNING id
111	            """;
112	
113	        try (Connection conn = database.getConnection();
114	             var stmt = conn.prepareStatement(sql)) {
115	
116	            stmt.setString(1, message.getChannel());
117	            stmt.setString(2, message.getTo());
118	            stmt.setString(3, message.getSubject());
119	            stmt.setString(4, message.getBody());
120	
121	            try (ResultSet rs = stmt.executeQuery()) {
122	                if (rs.next()) {
123	                    message.setId(rs.getLong("id"));
124	                }
125	            }
126	        } catch (SQLException e) {
127	            throw new RuntimeException("Failed to save message", e);
128	        }
129	
130	        return message;
131	    }
132	
133	    public List<Message> findAll() {
134	        List<Message> messages = new ArrayList<>();
135	        String sql = "SELECT * FROM messages ORDER BY id";
136	
137	        try (Connection conn = database.getConnection();
138	             var stmt = conn.createStatement();
139	             ResultSet rs = stmt.executeQuery(sql)) {
140	
141	            while (rs.next()) {
142	                messages.add(mapMessage(rs));
143	            }
144	        } catch (SQLException e) {
145	            throw new RuntimeException("Failed to fetch messages", e);
146	        }
147	        return messages;
148	    }
149	
150	    private Message mapMessage(ResultSet rs) throws SQLException {
151	        Message m = new Message();
152	        m.setId(rs.getLong("id"));
153	        m.setChannel(rs.getString("channel"));
154	        m.setTo(rs.getString("recipient"));
155	        m.setSubject(rs.getString("subject"));
156	        m.setBody(rs.getString("body"));
157	        return m;
158	    }
159	}
