     3	import com.pousadamarealta.domain.*;
     4	import com.pousadamarealta.service.PricingService;
     5	import org.junit.jupiter.api.BeforeEach;
     6	import org.junit.jupiter.api.Test;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	
    11	import static org.junit.jupiter.api.Assertions.assertEquals;
    12	
    13	public class PricingServiceTest {
    14	
    15	    private PricingService pricingService;
    16	
    17	    @BeforeEach
    18	    void setup() {
    19	        pricingService = new PricingService();
    20	    }
    21	
    22	    @Test
    23	    void testHighSeasonStandard() {
    24	        Reservation reservation = new Reservation();
    25	        reservation.setCheckIn(LocalDate.of(2027, 7, 10));
    26	        reservation.setCheckOut(LocalDate.of(2027, 7, 12));
    27	        reservation.setRatePlan(RatePlan.STANDARD);
    28	
    29	        Room room = new Room("101", RoomType.STANDARD);
    30	        pricingService.calculatePricing(reservation, room);
    31	
    32	        assertEquals(0, new BigDecimal("599.76").compareTo(reservation.getSubtotal()));
    33	        assertEquals(0, new BigDecimal("0.00").compareTo(reservation.getDiscount()));
    34	        assertEquals(0, new BigDecimal("599.76").compareTo(reservation.getTotal()));
    35	    }
    36	
    37	    @Test
    38	    void testCorporateTecnosul() {
    39	        Reservation reservation = new Reservation();
    40	        reservation.setCheckIn(LocalDate.of(2027, 3, 10));
    41	        reservation.setCheckOut(LocalDate.of(2027, 3, 12));
    42	        reservation.setRatePlan(RatePlan.CORPORATE);
    43	        reservation.setCompanyCode("TECNOSUL");
    44	
    45	        Room room = new Room("201", RoomType.DELUXE);
    46	        pricingService.calculatePricing(reservation, room);
    47	
    48	        assertEquals(0, new BigDecimal("779.80").compareTo(reservation.getSubtotal()));
    49	        assertEquals(0, new BigDecimal("93.58").compareTo(reservation.getDiscount()));
    50	        assertEquals(0, new BigDecimal("686.22").compareTo(reservation.getTotal()));
    51	    }
    52	
    53	    @Test
